    auto saved=captured;expect(extractGroove(played,8,{4},4,.25,16,captured).wasOk()&&captured.steps[1].active&&std::abs(captured.steps[1].offset-.2)<1e-12,"capture start is local to extraction and does not shift the reusable groove phase");expect(extractGroove({{3.95,.2,60,.8f}},8,{},0,.25,16,captured).wasOk()&&captured.steps[0].active&&std::abs(captured.steps[0].offset+.2)<1e-12,"late pickup nearest the next cycle wraps into groove cell zero");captured=saved;expect(extractGroove({{.125,.2,60,.8f}},8,{},0,.25,16,captured).failed()&&captured==saved,"halfway capture onsets reject instead of assigning an ambiguous cell");expect(extractGroove(played,8,{4},0,.25,16,captured).failed()&&captured==saved,"empty selected capture ranges retain the previous groove");expect(extractGroove(played,8,{},7,.25,16,captured).failed()&&captured==saved,"capture requires a complete cycle inside the source pattern");
    for(double grid:{0.,.01,4.1,std::nan(""),std::numeric_limits<double>::infinity()}){auto bad=settings;bad.pattern.grid=grid;expect(validateGroove(bad).failed(),"invalid groove grids reject");}for(double value:{-.001,1.001,std::nan("")}){auto bad=settings;bad.timing=value;expect(validateGroove(bad).failed(),"invalid groove strength rejects");}auto bad=settings;bad.pattern.steps.resize(33);expect(validateGroove(bad).failed(),"groove cell count is bounded");bad=settings;bad.pattern.grid=4;bad.pattern.steps.resize(32);expect(validateGroove(bad).failed(),"groove cycle cannot exceed supported sixty-four-beat pattern length");
    auto p=factories[2];p.id="personal-groove";p.name=String::fromUTF8("Мой грув");p.settings.pattern=captured;p.settings.timing=.617;p.settings.velocity=.437;p.settings.window=.175;p.settings.useWindow=true;auto file=root.getChildFile("groove-core.json");file.deleteFile();std::vector<GroovePreset> rows;expect(loadGroovePresets(file,rows).wasOk()&&rows.empty()&&groovePresetToken(file)=="missing","absent groove library starts empty without mutation");expect(putGroovePreset(file,p,false,"missing").wasOk()&&loadGroovePresets(file,rows).wasOk()&&rows.size()==1&&rows[0].name==p.name&&rows[0].settings==p.settings,"personal groove retains Unicode name sparse cells and every strength/window setting");auto json=groovePresetToJson(p);expect(!json.hasProperty("notes")&&!json.hasProperty("path")&&!json["settings"].hasProperty("start"),"groove preset stores musical settings without original notes paths or capture range");
    auto token=groovePresetToken(file),bytes=file.loadFileAsString();auto duplicate=p;duplicate.id="another-groove";duplicate.name=p.name.toUpperCase();expect(putGroovePreset(file,duplicate,false,token).failed()&&file.loadFileAsString()==bytes,"case-insensitive duplicate groove name cannot overwrite the catalog");p.name="Updated groove";expect(putGroovePreset(file,p,true,token).wasOk()&&loadGroovePresets(file,rows).wasOk()&&rows[0].name==p.name,"explicit groove update keeps its identity");bytes=file.loadFileAsString();expect(putGroovePreset(file,p,true,token).failed()&&removeGroovePreset(file,p.id,token).failed()&&file.loadFileAsString()==bytes,"stale groove update and deletion retain newer bytes");
    for(auto key:{"grid","timing","velocity","window","useWindow","steps"}){auto invalid=groovePresetToJson(p);invalid["settings"].getDynamicObject()->removeProperty(key);GroovePreset read=p;expect(groovePresetFromJson(invalid,read).failed()&&read.settings==p.settings,"incomplete groove settings reject without destination mutation");}for(auto value:{var(true),var("0.2"),var(-.5),var(.5),var(std::nan(""))}){auto invalid=groovePresetToJson(p);(*invalid["settings"]["steps"].getArray())[0].getDynamicObject()->setProperty("offset",value);GroovePreset read=p;expect(groovePresetFromJson(invalid,read).failed()&&read.settings==p.settings,"groove cell offsets reject nonnumeric nonfinite and out-of-range values");}for(auto value:{var(true),var("0.5"),var(-.001),var(1.001)}){auto invalid=groovePresetToJson(p);(*invalid["settings"]["steps"].getArray())[0].getDynamicObject()->setProperty("velocity",value);GroovePreset read;expect(groovePresetFromJson(invalid,read).failed(),"groove cell velocities reject bad JSON types and double ranges before float conversion");}
    auto invalid=groovePresetToJson(p);(*invalid["settings"]["steps"].getArray())[0].getDynamicObject()->setProperty("active",1);GroovePreset read;expect(groovePresetFromJson(invalid,read).failed(),"groove cell mode requires a JSON boolean");auto exchange=root.getChildFile("one-groove.pulsegroove");expect(saveGroovePresets(exchange,{p}).wasOk()&&loadGroovePresets(exchange,rows).wasOk()&&rows.size()==1&&rows[0].settings==p.settings,"single-groove export and relocation reproduce exact captured feel");auto envelope=JSON::parse(exchange);if(!envelope.getDynamicObject())return;envelope.getDynamicObject()->setProperty("schema",2);exchange.replaceWithText(JSON::toString(envelope));expect(loadGroovePresets(exchange,rows).failed()&&rows.size()==1,"future groove format rejects without clearing existing entries");file.replaceWithText("{corrupt groove");expect(putGroovePreset(file,p,true).failed()&&removeGroovePreset(file,p.id).failed()&&file.loadFileAsString()=="{corrupt groove","corrupt groove catalogs block all mutations");file.replaceWithText(bytes);expect(removeGroovePreset(file,p.id,groovePresetToken(file)).wasOk()&&loadGroovePresets(file,rows).wasOk()&&rows.empty(),"groove deletion removes exactly the selected identity");std::vector<GroovePreset> full;for(int i=0;i<maxGroovePresets;++i){auto row=p;row.id="groove-"+String(i);row.name="Groove "+String(i);full.push_back(row);}expect(saveGroovePresets(file,full).wasOk()&&putGroovePreset(file,p,false).failed(),"groove library capacity retains every existing preset");exchange.replaceWithText(String::repeatedString(" ",maxGroovePresetBytes+1));expect(loadGroovePresets(exchange,rows).failed()&&groovePresetToken(exchange)=="unavailable","oversized groove files reject before JSON parsing");
    auto song=emptyProject();song.bpm=120;song.swing=0;song.loop=false;song.patterns[0].length=4;song.tracks[7].send=0;song.patterns[0].lanes[7]={{.25,.5,60,.8f}};settings=factories[1].settings;expect(applyGroove(song.patterns[0].lanes[7],4,{},settings,out).wasOk(),"prepare audible grooved source");auto straight=render(song,assets,root,24000);song.patterns[0].lanes[7]=out;auto a=render(song,assets,root,24000,127),b=render(song,assets,root,24000,733);bool equal=true;double difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i){equal&=a.getSample(ch,i)==b.getSample(ch,i);difference+=std::abs(a.getSample(ch,i)-straight.getSample(ch,i));}expect(equal&&difference>1&&a.getMagnitude(0,0,24000)>.001,"groove changes actual playback timing and is sample-exact across callback sizes");RenderSettings renderSettings;renderSettings.bits=32;renderSettings.tailSeconds=0;auto output=root.getChildFile("groove-export.wav");auto result=renderAudio(song,assets,root,output,renderSettings);AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(output));AudioBuffer<float> decoded(2,24000);equal=result.wasOk()&&reader;if(equal){reader->read(&decoded,0,24000,0,true,true);for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)equal&=decoded.getSample(ch,i)==a.getSample(ch,i);}expect(equal,"grooved float WAV export matches callback audio sample for sample");
